export const getWeekQueryKey = (options?: Options<GetWeekData>) => createQueryKey('getWeek', options);

/**
 * Get Week
 *
 * The week board for the week containing `start` (default: today), Monday to Sunday.
 *
 * First moves unfinished tasks from past days to today and creates the week's missing
 * recurring tasks. Calling it again changes nothing.
 */
export const getWeekOptions = (options?: Options<GetWeekData>) => queryOptions<GetWeekResponse, GetWeekError, GetWeekResponse, ReturnType<typeof getWeekQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await getWeek({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: getWeekQueryKey(options)
});

const createInfiniteParams = <K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>>(queryKey: QueryKey<Options>, page: K) => {
    const params = { ...queryKey[0] };
    if (page.body) {
        params.body = {
            ...queryKey[0].body as any,
            ...page.body as any
        };
    }
    if (page.headers) {
        params.headers = {
            ...queryKey[0].headers,
            ...page.headers
        };
    }
    if (page.path) {
        params.path = {
            ...queryKey[0].path as any,
            ...page.path as any
        };
    }
    if (page.query) {
        params.query = {
            ...queryKey[0].query as any,
            ...page.query as any
        };
    }
    return params as unknown as typeof page;
};

export const getWeekInfiniteQueryKey = (options?: Options<GetWeekData>): QueryKey<Options<GetWeekData>> => createQueryKey('getWeek', options, true);

/**
 * Get Week
 *
 * The week board for the week containing `start` (default: today), Monday to Sunday.
 *
 * First moves unfinished tasks from past days to today and creates the week's missing
 * recurring tasks. Calling it again changes nothing.
 */
export const getWeekInfiniteOptions = (options?: Options<GetWeekData>) => {
    const opts = infiniteQueryOptions<GetWeekResponse, GetWeekError, InfiniteData<GetWeekResponse>, QueryKey<Options<GetWeekData>>, string | null | Pick<QueryKey<Options<GetWeekData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
    // @ts-ignore
    {
        queryFn: async ({ pageParam, queryKey, signal }) => {
            // @ts-ignore
            const page: Pick<QueryKey<Options<GetWeekData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
                query: {
                    start: pageParam
                }
            };
            const params = createInfiniteParams(queryKey, page);
            const { data } = await getWeek({
                ...options,
                ...params,
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: getWeekInfiniteQueryKey(options)
    });
    return opts as Omit<typeof opts, 'initialData'>;
};

